from ta_moler.cmd.airscale.genericairscale import GenericAirscale
from moler.exceptions import ParsingDone
import re


class Chk(GenericAirscale):
    """Chk command class."""

    def __init__(self, tags, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Chk command runs a diagnostic tool for gNB.

        :param tags:        List of tags used to describe groups of checks
                            eg. all - checks all groups
                                regular - those that are not necessary to run more than once
        :param connection:  moler connection to device, terminal when command is executed
        :param options:     command options as string
        :param prompt:      exepected prompt sending by device after command execution
        :param newline_chars:  Characters to split lines
        :param runner:      Runner to run command
        """
        super(Chk, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.tags = ' '.join(tags)
        self.current_ret['GROUPS'] = {}
        self.current_ret['SUMMARY'] = {}
        self._current_group_name = None

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return:    String representation of command to send over connection to device.
        """
        cmd = 'chk'
        if self.options:
            cmd = f"{cmd} {self.options}"

        cmd = f"{cmd} {self.tags}"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Parse received line to get expected value.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_diagnosis_group(line)
                self._parse_group_check_name(line)
                self._parse_summary(line)
            except ParsingDone:
                pass
        return super(Chk, self).on_new_line(line, is_full_line)

    # ++ [fct-0a] sysbshtopo      : rack topology and accesses between cpus
    _re_tag_group = re.compile(r"^\+{2}\s+\[\w+\-\w+\]\s+(?P<TAG_GROUP>\w+)")

    def _parse_diagnosis_group(self, line):
        """
        Parse output of command to extract gNB diagnosis information of tag groups.

        :param line:    output of command
        :return:        None
        """
        if self._regex_helper.search_compiled(Chk._re_tag_group, line):
            self._current_group_name = self._regex_helper.group('TAG_GROUP')
            self.current_ret['GROUPS'][self._current_group_name] = {}
            raise ParsingDone

    #   - backplane id = "2" .............................................. ok
    _re_group_check_name = re.compile(r"^\s+\-\s+(?P<CHECK_NAME>.*)\s+\.+\s+(?P<STATUS>\w+)")

    def _parse_group_check_name(self, line):
        """
        Parse output of command to extract name of the diagnosis check from specific tag group.

        :param line:    output of command
        :return:        None
        """
        if self._regex_helper.search_compiled(Chk._re_group_check_name, line):
            self.current_ret['GROUPS'][self._current_group_name][self._regex_helper.group('CHECK_NAME')] = \
                self._regex_helper.group('STATUS')
            raise ParsingDone

    # [fct-0a] # passed : 12
    _re_summary = re.compile(r"^\s+\[\w+\-\w+\]\s+(#\s+)?(?P<RESULT>\w+)\s+:\s+(?P<VALUE>.*)")

    def _parse_summary(self, line):
        """
        Parse output of command to extract summary information of from diagnosis.

        :param line:    output of command
        :return:        None
        """
        if self._regex_helper.search_compiled(Chk._re_summary, line):
            self.current_ret['SUMMARY'][self._regex_helper.group('RESULT')] = self._regex_helper.group('VALUE')
            raise ParsingDone


